mapper.select:
SELECT report_id, ym, DATE_FORMAT(created_at, '%Y-%m-%d %H:%i') created_at, status, sgg_cd
  FROM monthly_report
 WHERE report_id = #{reportId} AND user_id = #{userId}

mapper.sql:
 FROM survey_schedule s
 JOIN survey_plan sp ON sp.survey_id = s.survey_id
WHERE s.user_id = #{userId}

mapper.select:
SELECT DATE_FORMAT(s.sched_date, '%Y-%m-%d') day, COUNT(*) cnt, SUM() revisit

   AND s.sched_date >= #{from} AND s.sched_date < #{to}
 GROUP BY s.sched_date
